Canvas::Canvas(reader::lifecycle::Tracking tracking):tracking_(tracking),slots_(std::make_unique<std::array<Stroke,Slots>>()),scratch_(1632*2160,0),raster_(1620,2160,1632){}
bool Canvas::reserve()noexcept{if(active_>=0||!writable())return false;for(unsigned i=0;i<Slots;++i){unsigned free=Free;if((*slots_)[i].state.compare_exchange_strong(free,Active)){auto& s=(*slots_)[i];if(!tracking_.accept(s.tracking)){s.state=Free;return false;}active_=int(i);s.count=0;s.ignored=false;s.eraser=eraser_;s.hardwareEraser=false;s.started=false;s.interrupted=false;s.style=window_.style;contact_=true;return true;}}return false;}
std::size_t Canvas::room()const noexcept{if(active_<0)return 0;const auto& s=(*slots_)[active_];if(s.started&&s.ignored)return SIZE_MAX;const unsigned total=points_.load();if(s.count>=MaxPoints||total+s.count>=MaxTotal)return 0;return std::min<std::size_t>(MaxPoints-s.count,MaxTotal-total-s.count);}
bool Canvas::append(const spike::Point& p)noexcept{if(active_<0||failed_)return false;auto& s=(*slots_)[active_];auto fail=[&](bool limit){capacity_=limit;failed_=true;raster_.cancel();tracking_.complete(s.tracking,false);s.state.store(Failed,std::memory_order_release);active_=-1;contact_=false;return false;};if((!s.started&&p.phase!=spike::Phase::Down)||(s.started&&p.phase==spike::Phase::Down))return fail(false);if(p.phase==spike::Phase::Down){s.started=true;s.ignored=!window_.area.contains(p.x,p.y);s.hardwareEraser=p.eraser;s.eraser=s.eraser||p.eraser;if(!s.ignored&&!raster_.begin(s.style,matrix_,s.eraser))return fail(false);if(!s.ignored&&s.eraser&&generated_&&!generated_->begin(s.style,generatedMatrix_,true))return fail(false);}
 if(!s.ignored){if(s.count>=MaxPoints||points_.load()+s.count>=MaxTotal||p.eraser!=s.hardwareEraser){return fail(true);}styled::Coordinate point{double(std::clamp(p.x,window_.area.x0,window_.area.x1-1)-window_.area.x0),double(std::clamp(p.y,window_.area.y0,window_.area.y1-1)-window_.area.y0+window_.scroll)};if(!raster_.point(point,s.count==0)){return fail(false);}if(s.eraser&&generated_&&!generated_->point(point,s.count==0))return fail(false);s.points[s.count++]=point;}
 if(p.phase==spike::Phase::Up){contact_=false;if(s.ignored||!s.count){tracking_.complete(s.tracking,true);s.state=Free;active_=-1;return true;}raster_.end();if(s.eraser&&generated_)generated_->end();points_+=s.count;++strokes_;++pending_;s.state.store(Queued,std::memory_order_release);if(!queue_.push(unsigned(active_))){tracking_.complete(s.tracking,false);s.state=Failed;failed_=true;active_=-1;return false;}active_=-1;}return true;}
void Canvas::cancel()noexcept{if(active_>=0){raster_.cancel();if(generated_&&generated_->active())generated_->cancel();auto& slot=(*slots_)[active_];tracking_.complete(slot.tracking,slot.count==0);(*slots_)[active_].state=Free;active_=-1;}contact_=false;}
void Canvas::stop()noexcept{enabled_=false;if(active_>=0){raster_.cancel();if(generated_&&generated_->active())generated_->cancel();auto index=unsigned(active_);auto& s=(*slots_)[index];active_=-1;if(s.count){s.interrupted=true;failed_=true;points_+=s.count;++strokes_;++pending_;s.state.store(Queued,std::memory_order_release);if(!queue_.push(index)){tracking_.complete(s.tracking,false);--pending_;s.state=Failed;}}else{tracking_.complete(s.tracking,true);s.state=Free;}}contact_=false;}
bool Canvas::take(unsigned& at,QJsonObject& out,bool& eraser){if(!queue_.pop(at))return false;auto& s=(*slots_)[at];product::require(s.state.load(std::memory_order_acquire)==Queued,"note-stroke-queue-state");QJsonArray points;for(unsigned i=0;i<s.count;++i)points.append(QJsonArray{s.points[i].x,s.points[i].y});out={{"style",styled::jsonStyle(s.style)},{"points",points},{"coordinateSpace","note-canvas"}};if(s.interrupted)out["interrupted"]=true;eraser=s.eraser;return true;}
void Canvas::acknowledge(unsigned at,bool saved)noexcept{if(!saved){tracking_.complete((*slots_)[at].tracking,false);(*slots_)[at].state=Failed;failed_=true;return;}bool tracked=tracking_.complete((*slots_)[at].tracking,true);if(!tracked)failed_=true;(*slots_)[at].state.store((*slots_)[at].interrupted||!tracked?Failed:Free,std::memory_order_release);--pending_;}
void Canvas::install(const Window& window,std::span<const std::uint32_t> pixels,unsigned strokes,unsigned points){product::require(window.area.x0>=0&&window.area.y0>=0&&window.area.x1<=1620&&window.area.y1<=2160&&!window.area.empty(),"note-window-invalid");product::require(!contact_&&!pending_&&window.scroll>=0&&window.scroll<=16000&&strokes<=MaxStrokes&&points<=MaxTotal,"note-canvas-busy-or-capacity");generated_.reset();generatedArea_={};playbackPrepared_=false;window_=window;matrix_.value={1,0,0,1,double(window.area.x0),double(window.area.y0-window.scroll)};raster_.replace(pixels);std::fill(scratch_.begin(),scratch_.end(),0);strokes_=strokes;points_=points;capacity_=false;}
void Canvas::preparePlayback(QRectF bounds){product::require(!contact_&&!pending_,"note-playback-while-writing");playEnd();playbackPrepared_=true;product::require(std::isfinite(bounds.left())&&std::isfinite(bounds.top())&&std::isfinite(bounds.right())&&std::isfinite(bounds.bottom()),"note-playback-bounds");const auto area=window_.area;generatedArea_={std::max(area.x0,int(std::floor(bounds.left()))+area.x0-16),std::max(area.y0,int(std::floor(bounds.top()))+area.y0-window_.scroll-16),std::min(area.x1,int(std::ceil(bounds.right()))+area.x0+17),std::min(area.y1,int(std::ceil(bounds.bottom()))+area.y0-window_.scroll+17)};generated_.reset();if(generatedArea_.empty())return;generated_=std::make_unique<styled::Raster>(generatedArea_.x1-generatedArea_.x0,generatedArea_.y1-generatedArea_.y0,generatedArea_.x1-generatedArea_.x0);generatedMatrix_=matrix_;generatedMatrix_.value[4]-=generatedArea_.x0;generatedMatrix_.value[5]-=generatedArea_.y0;}
std::span<const std::uint32_t> Canvas::capturedInk()noexcept{if(!generated_)return raster_.pixels();std::copy(raster_.pixels().begin(),raster_.pixels().end(),scratch_.begin());const auto generated=generated_->pixels();const int stride=generatedArea_.x1-generatedArea_.x0;for(int y=generatedArea_.y0;y<generatedArea_.y1;++y)for(int x=generatedArea_.x0;x<generatedArea_.x1;++x){const auto at=std::size_t(y)*1632+x;const auto ink=generated[std::size_t(y-generatedArea_.y0)*stride+x-generatedArea_.x0];scratch_[at]=styled::combineInk(ink,scratch_[at]);}return scratch_;}
void Canvas::composite(spike::Surface out,std::span<const std::uint32_t> paper,spike::Rect r)const noexcept{if(!generated_)raster_.composite(out,paper,r);else{const auto generated=generated_->pixels(),base=raster_.pixels();const int stride=generatedArea_.x1-generatedArea_.x0;for(int y=std::max(0,r.y0);y<std::min(2160,r.y1);++y)for(int x=std::max(0,r.x0);x<std::min(1620,r.x1);++x){const auto at=std::size_t(y)*1632+x;const auto behind=generatedArea_.contains(x,y)?generated[std::size_t(y-generatedArea_.y0)*stride+x-generatedArea_.x0]:0;out.pixels[std::size_t(y)*out.stridePixels+x]=styled::compositeInk(paper[at],styled::combineInk(behind,base[at]));}}for(int y=std::max(0,r.y0);y<std::min(2160,r.y1);++y)for(int x=std::max(0,r.x0);x<std::min(1620,r.x1);++x)if(!window_.area.contains(x,y))out.pixels[std::size_t(y)*out.stridePixels+x]=paper[std::size_t(y)*1632+x];}
std::vector<std::uint32_t> render(const QJsonArray& strokes,const Window& window){product::require(strokes.size()<=MaxStrokes,"note-stroke-capacity");styled::Raster raster(1620,2160,1632);styled::Matrix matrix{{1,0,0,1,double(window.area.x0),double(window.area.y0-window.scroll)}};unsigned total=0;for(auto value:strokes){const auto stroke=value.toObject();const auto points=stroke["points"].toArray();product::require(!points.isEmpty()&&points.size()<=2048,"note-point-capacity");if(stroke["shape"]=="polygon"){total+=unsigned(points.size());for(auto hole:stroke["holes"].toArray())total+=unsigned(hole.toArray().size());product::require(total<=MaxTotalPoints,"note-total-point-capacity");raster.fill(stroke,matrix);continue;}product::require(raster.begin(styled::parseStyle(stroke["style"].toObject()),matrix),"note-replay-begin");for(int i=0;i<points.size();++i){auto point=points[i].toArray();product::require(point.size()>=2&&++total<=MaxTotalPoints,"note-total-point-capacity");product::require(raster.point({point[0].toDouble(),point[1].toDouble()},i==0),"note-replay-budget");}raster.end();}return {raster.pixels().begin(),raster.pixels().end()};}
